  const minScore: Score := 0

  // Student record with their score and rank
  class Student {
    var id: StudentId
    var score: Score
    var rank: Rank

    constructor(initId: StudentId, initScore: Score) {
      id := initId;
      score := initScore;
      rank := 0;
    }
  }

  // Tutor record with availability status
  class Tutor {
    var id: TutorId
    var isAvailable: bool
    var maxAssignments: int  // Maximum assignments this tutor can handle

    constructor(initId: TutorId, initAvailable: bool, initMax: int) {
      id := initId;
      isAvailable := initAvailable;
      maxAssignments := initMax;
    }
  }

  // Assignment record linking student, tutor, and score
  class Assignment {
    var id: AssignmentId
    var studentId: StudentId
    var tutorId: TutorId
    var assignedScore: Score

    constructor(initId: AssignmentId, sId: StudentId, tId: TutorId, score: Score) {
      id := initId;
      studentId := sId;
      tutorId := tId;
      assignedScore := score;
    }
  }

