    var students: seq<Student>
    var tutors: seq<Tutor>
    var assignments: seq<Assignment>
    var tutorShortage: bool

    // Constructor
    constructor(studentScores: seq<Score>, tutorAvailabilities: seq<bool>, tutorCapacities: seq<int>) 
      requires |studentScores| > 0
      requires |tutorAvailabilities| > 0
      requires |tutorCapacities| == |tutorAvailabilities|
      requires forall i :: 0 <= i < |studentScores| ==> minScore <= studentScores[i] <= maxScore
    {
      // Initialize students
      students := [];
      var i := 0;
      while i < |studentScores|
        invariant 0 <= i <= |studentScores|
        invariant |students| == i
        invariant forall j :: 0 <= j < i ==> students[j].id == j && students[j].score == studentScores[j]
      {
        students := students + [new Student(i, studentScores[i])];
        i := i + 1;
      }

      // Initialize tutors
      tutors := [];
      i := 0;
      while i < |tutorAvailabilities|
        invariant 0 <= i <= |tutorAvailabilities|
        invariant |tutors| == i
        invariant forall j :: 0 <= j < i ==> 
          tutors[j].id == j && 
          tutors[j].isAvailable == tutorAvailabilities[j] &&
          tutors[j].maxAssignments == tutorCapacities[j]
      {
        tutors := tutors + [new Tutor(i, tutorAvailabilities[i], tutorCapacities[i])];
        i := i + 1;
      }

      assignments := [];
      tutorShortage := false;
    }

    // Method to calculate ranks based on scores
    method CalculateRanks() 
      modifies this
      ensures forall i, j :: 0 <= i < j < |students| && students[i].score > students[j].score ==> 
