      // First, sort students by score in descending order
      var sortedStudents := students;
      var sorted := false;

      // Simple bubble sort for ranking
      while !sorted
        invariant |sortedStudents| == |students|
        invariant forall k :: 0 <= k < |students| ==> exists j :: 0 <= j < |students| && students[j].id == sortedStudents[k].id
      {
        sorted := true;
        var idx := 0;
        while idx < |sortedStudents| - 1
          invariant 0 <= idx <= |sortedStudents|
        {
          if sortedStudents[idx].score < sortedStudents[idx + 1].score {
            // Swap
            var temp := sortedStudents[idx];
            sortedStudents[idx] := sortedStudents[idx + 1];
            sortedStudents[idx + 1] := temp;
            sorted := false;
          }
          idx := idx + 1;
        }
