        var sameScoreCount := 1;
        var j := idx + 1;
        while j < |sortedStudents| && sortedStudents[j].score == sortedStudents[idx].score
          invariant idx < j <= |sortedStudents|
        {
          sameScoreCount := sameScoreCount + 1;
          j := j + 1;
        }

        // Assign the same rank to all students with this score
        var k := idx;
        while k < j
          invariant idx <= k <= j
        {
          // Update rank in the original students array
          var studentId := sortedStudents[k].id;
          students[studentId].rank := currentRank;
          k := k + 1;
        }

        // Move to next rank group
        currentRank := currentRank + sameScoreCount;
        idx := j;
      }
    }

