    method ProcessAssignments() returns (processed: bool)
      modifies this
      ensures processed ==> |assignments| == |students|
      ensures processed ==> forall i :: 0 <= i < |students| ==> students[i].rank > 0
    {
      // Calculate ranks first
      CalculateRanks();

      // Then assign tutors
      var assignmentSuccess := AssignTutorsToAssignments();

      processed := assignmentSuccess;
    }

    // Get student ranks for output
    method GetStudentRanks() returns (ranks: seq<Rank>)
      ensures |ranks| == |students|
      ensures forall i :: 0 <= i < |ranks| ==> ranks[i] == students[i].rank
    {
      ranks := [];
      var i := 0;
      while i < |students|
        invariant 0 <= i <= |students|
        invariant |ranks| == i
        invariant forall j :: 0 <= j < i ==> ranks[j] == students[j].rank
      {
        ranks := ranks + [students[i].rank];
        i := i + 1;
      }
    }
  }

  // Example usage and verification
  method ExampleUsage() {
    // Create sample data
    var studentScores: seq<Score> := [85, 92, 78, 92, 88];  // Note: two students with score 92
    var tutorAvailabilities: seq<bool> := [true, true, false, true];
