// Type definitions
type Address = int
type Weight = real
type Slice = (Address, Address)  // start, end (exclusive)

// Function to check if a slice is valid (start < end)
function ValidSlice(s: Slice): bool
  s.0 < s.1

// Function to get slice size
function SliceSize(s: Slice): int
  requires ValidSlice(s)
  s.1 - s.0

// Function to split a slice into two equal halves
function SplitSlice(s: Slice): (Slice, Slice)
  requires ValidSlice(s)
  ensures ValidSlice(result.0) && ValidSlice(result.1)
  ensures SliceSize(s) == SliceSize(result.0) + SliceSize(result.1)
{
  var mid := s.0 + (s.1 - s.0) / 2;
  ((s.0, mid), (mid, s.1))
}

// SliceDict type - a set of slices with weights
type SliceDict = map<Slice, Weight>

// Function to check if slices in dictionary are valid and non-overlapping
predicate ValidSliceDict(sd: SliceDict)
  (forall s :: s in sd ==> ValidSlice(s)) &&
  (forall s1, s2 :: s1 in sd && s2 in sd && s1 != s2 ==> 
    s1.1 <= s2.0 || s2.1 <= s1.0)

// Function to compute total allocated weight
function TotalWeight(sd: SliceDict): Weight
  requires ValidSliceDict(sd)
{
