predicate ValidRatio(students: StudentList, tutors: TutorList, minRatio: int, maxRatio: int)
  requires minRatio > 0 && maxRatio >= minRatio
{
  |students| > 0 ==> |tutors| > 0 &&
  |students| >= minRatio * |tutors| &&
  |students| <= maxRatio * |tutors|
}

predicate BalancedAssignment(students: StudentList, tutors: TutorList)
  requires |students| > 0 && |tutors| > 0
{
  // Each student has at least one tutor, each tutor has reasonable number of students
  exists ratio: int :: ratio > 0 && 
    |students| == ratio * |tutors|
}

method AssignmentsToMark(students: StudentList, tutors: TutorList, minRatio: int, maxRatio: int) 
  returns (result: TutorList)
  requires minRatio > 0 && maxRatio >= minRatio
  requires |students| > 0
  ensures |result| > 0
  ensures ValidRatio(students, result, minRatio, maxRatio)
  decreases |students|
