  // Base case: if we have enough tutors for the current students
  if |tutors| > 0 && ValidRatio(students, tutors, minRatio, maxRatio) {
    result := tutors;
    return;
  }

  // Recursive case: need to adjust tutors
  var newTutors: TutorList := tutors;

  // Add tutors if ratio is too high (too many students per tutor)
  if |students| > maxRatio * (if |tutors| == 0 then 1 else |tutors|) {
    // Calculate how many tutors we need
    var neededTutors := (|students| + maxRatio - 1) / maxRatio;
    var additionalTutors := neededTutors - |tutors|;

    // Create new tutors
    var i := 0;
    while i < additionalTutors
      invariant i <= additionalTutors
      invariant |newTutors| == |tutors| + i
    {
      newTutors := newTutors + [Tutor(|tutors| + i)];
      i := i + 1;
    }
  }

