  ghost var allocatedStudents: set<Student>
  ghost var allocatedTutors: set<Tutor>
  ghost var allocationMap: map<Tutor, set<Student>>

  // Predicate to check if allocation is valid
  predicate ValidAllocation()
    reads allocatedStudents, allocatedTutors, allocationMap
  {
    // All allocated students are unique
    |allocatedStudents| <= maxStudents &&

    // All allocated tutors are unique  
    |allocatedTutors| <= maxTutors &&

    // Each tutor has at most maxStudentsPerTutor students
    (forall tutor :: tutor in allocatedTutors ==> 
        |allocationMap[tutor]| <= maxStudentsPerTutor) &&

    // All students in allocationMap are allocated
    (forall tutor :: tutor in allocatedTutors ==>
        allocationMap[tutor] <= allocatedStudents) &&

    // No student is assigned to multiple tutors
    (forall tutor1, tutor2 :: 
