    returns (assignments: map<Tutor, seq<Student>>)
    requires forall i, j :: 0 <= i < j < |tutors| ==> IsOrderable(tutors[i], tutors[j])
    requires forall i, j :: 0 <= i < j < |students| ==> IsOrderable(students[i], students[j])
    ensures forall t: Tutor :: t in tutors ==> 
