    var studentIndex := 0;
    var tutorIndex := 0;

    while studentIndex < |students| && tutorIndex < |tutors|
      invariant 0 <= studentIndex <= |students|
      invariant 0 <= tutorIndex <= |tutors|
      invariant forall t: Tutor :: t in tutors[..tutorIndex] ==>
